/**
 * Finding output.
 *
 * Findings are written in the System Feedback register, which is the register
 * they belong to: they are generated by a system event and their job is to
 * report what happened and what to do next. That means every finding states
 * what was found, where, why it is a violation, and what to use instead.
 *
 * A rule identifier alone is not a sufficient finding, so the formatters below
 * never emit one on its own.
 */

import type { Finding, LintResult } from './index.js';

const SEVERITY_LABEL = {
  blocking: 'blocking',
  substantive: 'substantive',
  minor: 'minor',
} as const;

function formatFinding(f: Finding): string {
  const head = `  ${f.file}:${f.line}:${f.column}  ${SEVERITY_LABEL[f.severity]}  [${f.ruleId}]`;
  const lines = [head, `    Found: "${f.found}"`, `    Why:   ${f.reason}`, `    Use:   ${f.replacement}`];

  if (f.needsConfirmation) {
    lines.push('    Note:  This pattern is not conclusive on its own. Confirm before changing.');
  }
  if (f.overriddenBy) {
    lines.push(`    Override (${f.overriddenBy.source}): ${f.overriddenBy.reason}`);
  }

  return lines.join('\n');
}

export function formatText(results: LintResult[], failOn: string): string {
  const out: string[] = [];

  const active = results.flatMap((r) => r.findings.filter((f) => !f.overriddenBy));
  const overridden = results.flatMap((r) => r.findings.filter((f) => f.overriddenBy));
  const badOverrides = results.flatMap((r) =>
    r.invalidOverrides.map((o) => ({ ...o, file: r.file })),
  );

  for (const result of results) {
    const reportable = result.findings.filter((f) => !f.overriddenBy);
    if (reportable.length === 0) continue;
    out.push('', ...reportable.map(formatFinding));
  }

  if (badOverrides.length > 0) {
    out.push('', 'Overrides without a recorded reason:');
    for (const o of badOverrides) {
      out.push(
        `  ${o.file}${o.line ? `:${o.line}` : ''}  [${o.rule}] (${o.scope})`,
        '    An override records why a rule does not apply here. Without a reason it is',
        '    a silent suppression, which removes the evidence that anything was wrong.',
        '    Add a rationale of at least eight characters, or remove the override.',
      );
    }
  }

  const counts = { blocking: 0, substantive: 0, minor: 0 };
  for (const f of active) counts[f.severity]++;

  out.push(
    '',
    `${results.length} file${results.length === 1 ? '' : 's'} checked. ` +
      `${counts.blocking} blocking, ${counts.substantive} substantive, ${counts.minor} minor.` +
      (overridden.length ? ` ${overridden.length} overridden.` : ''),
  );

  const skipped = new Set(results.flatMap((r) => r.skippedRegisterRules));
  if (skipped.size > 0) {
    out.push(
      `${skipped.size} register-scoped rule${skipped.size === 1 ? '' : 's'} were not run, because no register was declared for those files.`,
      'Declare one per path in .ekdotico-lint.json to enable them. Register classification is not inferred.',
    );
  }

  out.push(
    '',
    'This linter checks the mechanical subset of the Expression Guidelines. Register',
    'classification, evaluative inference, deficit framing, anthropomorphism, and factual',
    'currency are not checked and remain the responsibility of review.',
  );

  if (active.length > 0) {
    out.push(`Failing on ${failOn} and above.`);
  }

  return out.join('\n');
}

export function formatJson(results: LintResult[]): string {
  return JSON.stringify(
    {
      files: results.length,
      findings: results.flatMap((r) => r.findings),
      invalidOverrides: results.flatMap((r) =>
        r.invalidOverrides.map((o) => ({ ...o, file: r.file })),
      ),
      skippedRegisterRules: [...new Set(results.flatMap((r) => r.skippedRegisterRules))],
    },
    null,
    2,
  );
}
